proguardAdditions.insert:
-dontwarn com.tencent.**
-keep class com.tencent.** { *;}
-keepclassmembers class com.tencent.**{*;}

-keepclasseswithmembers class * {
... *JNI*(...);
}

-keepclasseswithmembernames class * {
... *JRI*(...);
}

-keep class **JNI* {*;}
-keep class android.app.** {
*;
}
